-- master.chklist_requirement_rule definition
-- Drop table
-- DROP TABLE master.chklist_requirement_rule;

create table master.chklist_requirement_rule ( chk_id uuid default gen_random_uuid() not null,
	chk_cd varchar(50) not null,
	module_code varchar(50) not null,
	requirement_type varchar(30) not null,
	title varchar(255) not null,
	description text null,
	input_schema jsonb null,
	show_if jsonb null,
	inherit_from jsonb null,
	sync_to_parent jsonb null,
	min_responses_required int4 default 1 not null,
	is_mandatory bool default true not null,
	display_order int4 default 0 not null,
	local_vernacular text null,
	is_active bool default true not null,
	entry_ts timestamp(3) default CURRENT_TIMESTAMP not null,
	updt_ts timestamp(3) default CURRENT_TIMESTAMP not null,
	entry_by varchar(50) null,
	updt_by varchar(50) null,
	constraint chklist_requirement_rule_pkey primary key (chk_id),
	constraint chklist_requirement_rule_unq unique (chk_cd,
	description));
-- Permissions

alter table master.chklist_requirement_rule owner to postgres;

grant all on
table master.chklist_requirement_rule to postgres;


